from pathlib import Path

root = Path(__file__).resolve().parents[1] / 'frontend/src'

def replace_template(name, icons, template):
    path = root / 'views' / name
    old = path.read_text(encoding='utf-8')
    script = old[:old.index('</script>') + len('</script>')]
    script = script.replace("import PageHeading", f"import {{ {icons} }} from '@element-plus/icons-vue'\nimport PageHeading")
    path.write_text(script + '\n' + template.strip() + '\n', encoding='utf-8')

